368	/// "Hoje"/"Ontem"/`dd/mm/yyyy` — presentation's own job (Code Map: day
369	/// labels aren't the pure `groupEntriesByDate()`'s concern). [date] is
370	/// always already truncated to local midnight (`EntryDateGroup`'s own
371	/// contract).
372	String _dayLabel(DateTime date) {
373	  final now = DateTime.now();
374	  final today = DateTime(now.year, now.month, now.day);
375	  final yesterday = today.subtract(const Duration(days: 1));
376	  if (date == today) {
377	    return 'Hoje';
378	  }
379	  if (date == yesterday) {
380	    return 'Ontem';
381	  }
382	  final day = date.day.toString().padLeft(2, '0');
383	  final month = date.month.toString().padLeft(2, '0');
384	  return '$day/$month/${date.year}';
385	}
