73	/// A plain (non-mocktail) fake — queues one `list()` result per call, same
74	/// rationale as `meus_registros_cubit_test.dart`'s own fake, plus an
75	/// optional [firstCallGate] so a test can hold the very first `list()`
76	/// call unresolved to observe the skeleton's 300ms threshold.
77	class _FakeEntriesRepository implements EntriesRepository {
78	  final List<Either<Failure, EntriesPage>> _listResults = [];
79	  int listCallCount = 0;
80	  Completer<void>? firstCallGate;
81	
82	  void queueList(Either<Failure, EntriesPage> result) {
83	    _listResults.add(result);
84	  }
85	
86	  @override
87	  Future<Either<Failure, Entry>> create({
88	    required String content,
89	    required EntrySource source,
90	    int? mediaDurationSeconds,
91	  }) async => throw UnimplementedError('not expected to be called');
92	
93	  @override
94	  Future<Either<Failure, EntriesPage>> list({
95	    String? cursor,
96	    int limit = 20,
97	  }) async {
98	    listCallCount++;
99	    if (listCallCount == 1 && firstCallGate != null) {
100	      await firstCallGate!.future;
101	    }
102	    if (_listResults.isEmpty) {
103	      throw StateError('no queued list() result for call #$listCallCount');
104	    }
105	    return _listResults.removeAt(0);
106	  }
107	}
