135	/// A controllable `PendingEntryWriteTracker` fake — unlike the trivial one
136	/// above (whose streams never emit), this one lets a test drive
137	/// [pendingWrites] directly and records every [retry] call, so a test can
138	/// assert the real screen's own tap-to-retry wiring
139	/// (`meus_registros_screen.dart`'s `onRetryTap: (entry) =>
140	/// widget.cubit.retry(entry.id)`) actually reaches the tracker with the
141	/// right `tempId` — Review finding (round 2): this exact chain (screen tap
142	/// -> cubit.retry(entry.id) -> tracker.retry(tempId)) had no end-to-end
143	/// coverage before; every other link in it was only ever exercised in
144	/// isolation (`entry_record_card_test.dart`, `meus_registros_cubit_test.
145	/// dart`).
146	class _ControllablePendingEntryWriteTracker
147	    implements PendingEntryWriteTracker {
148	  final _pendingController =
149	      StreamController<List<PendingEntryWrite>>.broadcast();
150	  final List<String> retryCalls = [];
151	
152	  void emitPendingWrites(List<PendingEntryWrite> writes) =>
153	      _pendingController.add(writes);
154	
155	  @override
156	  Stream<List<PendingEntryWrite>> get pendingWrites =>
157	      _pendingController.stream;
158	
159	  @override
160	  Stream<({String tempId, Entry entry})> get confirmedWrites =>
161	      const Stream.empty();
162	
163	  @override
164	  Future<Either<Failure, Entry>> create({
165	    required String content,
166	    required EntrySource source,
167	    int? mediaDurationSeconds,
168	  }) async => throw UnimplementedError('not expected to be called');
169	
170	  @override
171	  Future<void> retry(String tempId) async {
172	    retryCalls.add(tempId);
173	  }
174	
175	  @override
176	  Future<void> dispose() async {
177	    await _pendingController.close();
178	  }
179	}
