          const SizedBox(height: DesignTokens.spacingSm),
          for (final entry in group.entries) ...[
            EntryRecordCard(
              key: ValueKey(entry.id),
              entry: entry,
              badgeState: badgeFor(entry),
              onTap: () => onCardTap(entry),
              onRetryTap: () => onRetryTap(entry),
            ),
            const SizedBox(height: DesignTokens.spacingSm),
          ],
        ],
      ),
