1	import 'package:flutter_test/flutter_test.dart';
2	import 'package:fpdart/fpdart.dart';
3	import 'package:hive_ce_flutter/hive_ce_flutter.dart';
4	import 'package:mocktail/mocktail.dart';
5	import 'package:path_provider_platform_interface/path_provider_platform_interface.dart';
6	
7	import 'package:cerne/features/entries/data/datasources/entries_remote_data_source.dart';
8	import 'package:cerne/features/entries/data/models/entry_dto.dart';
9	import 'package:cerne/features/entries/data/repositories/entries_repository_impl.dart';
10	import 'package:cerne/features/entries/domain/entities/entry.dart';
11	
12	import '../../../../support/fake_path_provider_platform.dart';
13	
14	class MockEntriesRemoteDataSource extends Mock
15	    implements EntriesRemoteDataSource {}
16	
17	const _dto = EntryDto(
18	  id: 'e1',
19	  content: 'Hoje foi um bom dia.',
20	  source: EntrySource.manual,
21	  chatMessageId: null,
22	  occurredAt: '2026-01-01T00:00:00Z',
23	  serverRevision: 1,
24	  createdAt: '2026-01-01T00:00:00Z',
25	  updatedAt: '2026-01-01T00:00:00Z',
26	);
27	
28	/// Review finding: `entries_repository_impl_test.dart`'s own `MockBox`
29	/// (`when(() => mockBox.put(any(), any())).thenAnswer((_) async {})`)
30	/// always succeeds and never actually encodes anything — it proves
31	/// `create()`'s own control flow, but never exercises real `hive_ce`
32	/// encoding of `EntryDto.toJson()`'s actual shape (an enum value, a
33	/// nullable field, ints, ISO date strings). This suite opens a *real*,
34	/// temp-dir-backed `Box<Map>` instead — same `FakePathProviderPlatform`/
35	/// `Hive.initFlutter()` bootstrap `bootstrap_integration_test.dart`
36	/// already uses for exactly this reason — so the write-through is proven
37	/// against the real Hive backend, not a mock.
38	void main() {
39	  TestWidgetsFlutterBinding.ensureInitialized();
40	
41	  setUpAll(() {
42	    registerFallbackValue(EntrySource.manual);
43	  });
44	
45	  late FakePathProviderPlatform fakePathProvider;
46	  late Box<Map> box;
47	  late MockEntriesRemoteDataSource mockRemoteDataSource;
48	  late EntriesRepositoryImpl repository;
49	
50	  setUp(() async {
51	    fakePathProvider = FakePathProviderPlatform();
52	    PathProviderPlatform.instance = fakePathProvider;
53	    await Hive.initFlutter();
54	    box = await Hive.openBox<Map>('entries_integration_test');
55	
56	    mockRemoteDataSource = MockEntriesRemoteDataSource();
57	    repository = EntriesRepositoryImpl(
58	      remoteDataSource: mockRemoteDataSource,
59	      entriesBox: box,
60	    );
61	  });
62	
63	  tearDown(() async {
64	    await Hive.close();
65	    await fakePathProvider.cleanUp();
66	  });
67	
68	  test(
69	    'writes the real Hive-encoded EntryDto.toJson() shape and reads it '
70	    'back verbatim — enum, nullable field, ints, and ISO date strings all '
71	    'round-trip through the actual hive_ce backend, not a mock',
72	    () async {
73	      when(
74	        () => mockRemoteDataSource.create(
75	          content: any(named: 'content'),
76	          source: any(named: 'source'),
77	        ),
78	      ).thenAnswer((_) async => right(_dto));
79	
80	      final result = await repository.create(
81	        content: 'Hoje foi um bom dia.',
82	        source: EntrySource.manual,
83	      );
84	
85	      expect(result.isRight(), isTrue);
86	
87	      final stored = box.get('e1');
88	      expect(stored, isNotNull);
89	      expect(stored!['id'], 'e1');
90	      expect(stored['content'], 'Hoje foi um bom dia.');
91	      expect(stored['source'], 'manual');
92	      expect(stored['chatMessageId'], isNull);
93	      expect(stored['occurredAt'], '2026-01-01T00:00:00Z');
94	      expect(stored['serverRevision'], 1);
95	      expect(stored['createdAt'], '2026-01-01T00:00:00Z');
96	      expect(stored['updatedAt'], '2026-01-01T00:00:00Z');
97	
98	      // Re-decoding the stored map back through EntryDto.fromJson proves
99	      // the round trip is lossless, not just individually-matching
100	      // fields.
101	      final decoded = EntryDto.fromJson(stored.cast<String, dynamic>());
102	      expect(decoded.id, _dto.id);
103	      expect(decoded.source, _dto.source);
104	    },
105	  );
106	
107	  test(
108	    'a non-null chatMessageId also round-trips correctly through the real '
109	    'box',
110	    () async {
111	      const chatDto = EntryDto(
112	        id: 'e2',
113	        content: 'Registrado a partir do chat.',
114	        source: EntrySource.chat,
115	        chatMessageId: 'm1',
116	        occurredAt: '2026-01-02T00:00:00Z',
117	        serverRevision: 1,
118	        createdAt: '2026-01-02T00:00:00Z',
119	        updatedAt: '2026-01-02T00:00:00Z',
120	      );
121	      when(
122	        () => mockRemoteDataSource.create(
123	          content: any(named: 'content'),
124	          source: any(named: 'source'),
125	        ),
126	      ).thenAnswer((_) async => right(chatDto));
127	
128	      await repository.create(
129	        content: 'Registrado a partir do chat.',
130	        source: EntrySource.chat,
131	      );
132	
133	      final stored = box.get('e2');
134	      expect(stored!['chatMessageId'], 'm1');
135	      expect(stored['source'], 'chat');
136	    },
137	  );
138	
139	  test(
140	    'spec-3-2: a non-null mediaDurationSeconds round-trips through the '
141	    'real box; a null one is omitted from the stored map entirely '
142	    '(includeIfNull: false), not stored as an explicit null',
143	    () async {
144	      const audioDto = EntryDto(
145	        id: 'e3',
146	        content: 'Transcrição de áudio.',
147	        source: EntrySource.audio,
148	        chatMessageId: null,
149	        occurredAt: '2026-01-03T00:00:00Z',
150	        serverRevision: 1,
151	        createdAt: '2026-01-03T00:00:00Z',
152	        updatedAt: '2026-01-03T00:00:00Z',
153	        mediaDurationSeconds: 42,
154	      );
155	      when(
156	        () => mockRemoteDataSource.create(
157	          content: any(named: 'content'),
158	          source: any(named: 'source'),
159	          mediaDurationSeconds: any(named: 'mediaDurationSeconds'),
160	        ),
161	      ).thenAnswer((_) async => right(audioDto));
162	
163	      await repository.create(
164	        content: 'Transcrição de áudio.',
165	        source: EntrySource.audio,
166	        mediaDurationSeconds: 42,
167	      );
168	
169	      final stored = box.get('e3');
170	      expect(stored!['mediaDurationSeconds'], 42);
171	
172	      // A manual entry (no mediaDurationSeconds at all) stores no such
173	      // key — never an explicit `null` value.
174	      when(
175	        () => mockRemoteDataSource.create(
176	          content: any(named: 'content'),
177	          source: any(named: 'source'),
178	          mediaDurationSeconds: any(named: 'mediaDurationSeconds'),
179	        ),
180	      ).thenAnswer((_) async => right(_dto));
181	      await repository.create(
182	        content: 'Hoje foi um bom dia.',
183	        source: EntrySource.manual,
184	      );
185	      final manualStored = box.get('e1');
186	      expect(manualStored, isNotNull);
187	      expect(manualStored!.containsKey('mediaDurationSeconds'), isFalse);
188	    },
189	  );
190	}
